def check_discriminant_square(Y):
    """Checks if Y(Y-4) is a perfect square M^2."""
    if Y <= 0:
        return False
    if Y == 1:
        return False

    target = Y * (Y - 4)
    if target < 0:
        return False

    M_float = target**0.5
    M_int = int(round(M_float))

    is_square = M_int**2 == target
    return is_square, M_int

# Search for Y = K1*K2 > 4
# We check a range where we expect failure based on Diophantine analysis.
Y_values = range(5, 50) 

results = []
for Y in Y_values:
    is_square, M = check_discriminant_square(Y)
    if is_square:
        results.append((Y, M))

print("Results for Y=K1*K2 > 4:")
if results:
    for Y, M in results:
        print(f"Y={Y}, M={M}. Discriminant is a perfect square.")
else:
    print("No solutions found for Y(Y-4) = M^2 with Y > 4.")

